#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <math.h>

static uint32_t u32le(const unsigned char *p) {
  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}
static uint16_t u16le(const unsigned char *p) {
  return (uint16_t)p[0] | ((uint16_t)p[1] << 8);
}

int main(int argc, char **argv) {
  if (argc != 2) { fprintf(stderr, "usage: %s mono16.wav\n", argv[0]); return 2; }
  FILE *f = fopen(argv[1], "rb"); if (!f) return 3;
  unsigned char h[12]; if (fread(h,1,12,f)!=12) return 4;
  uint32_t rate=0, data_len=0; long data_pos=0; uint16_t channels=0,bits=0;
  while (fread(h,1,8,f)==8) {
    uint32_t n=u32le(h+4); long next=ftell(f)+n+(n&1);
    if (!memcmp(h,"fmt ",4)) {
      unsigned char b[32]={0}; if(n>32) return 5; fread(b,1,n,f);
      channels=u16le(b+2); rate=u32le(b+4); bits=u16le(b+14);
    } else if (!memcmp(h,"data",4)) { data_pos=ftell(f); data_len=n; break; }
    fseek(f,next,SEEK_SET);
  }
  if(channels!=1 || bits!=16 || !rate || !data_pos) { fprintf(stderr,"need mono pcm16\n"); return 6; }
  fseek(f,data_pos,SEEK_SET);
  int bin=(int)llround(rate*0.005); int16_t *x=malloc(bin*2); uint64_t idx=0;
  printf("bin,time,peak,rms,zcr\n");
  while(1) {
    size_t got=fread(x,2,bin,f); if(!got) break;
    int peak=0,zcr=0; double ss=0; int prev=x[0]>=0;
    for(size_t i=0;i<got;i++) { int v=x[i],a=v<0?-v:v; if(a>peak)peak=a; ss+=(double)v*v; int s=v>=0; if(i&&s!=prev)zcr++; prev=s; }
    printf("%llu,%.6f,%d,%.3f,%d\n",(unsigned long long)idx,idx*0.005,peak,sqrt(ss/got),zcr);
    idx++;
  }
  free(x); fclose(f); return 0;
}

