#!/usr/bin/env python3
import csv, json, sys

path = sys.argv[1]
threshold = int(sys.argv[2]) if len(sys.argv) > 2 else 1800
bins = []
with open(path, newline="") as f:
    for r in csv.DictReader(f):
        bins.append((int(r["peak"]), float(r["rms"]), int(r["zcr"])))

# A racquet strike is broadband and impulsive: retain sharp local maxima, then
# enforce a short refractory period so a single ringing impact is counted once.
raw=[]
for i in range(10, len(bins)-10):
    p,r,z=bins[i]
    if p >= threshold and p == max(x[0] for x in bins[i-8:i+9]) and p/(r+1) >= 2.5:
        raw.append((i,p,r,z))
events=[]
for x in raw:
    if events and x[0]-events[-1][0] < 40: # ~0.20 s
        if x[1] > events[-1][1]: events[-1]=x
    else: events.append(x)

# Use sample-clock time: bins contain 55 samples at 11025 Hz.
def sec(i): return i*55/11025

# Build permissive hit trains. Tennis inter-hit spacing is normally 1.0-1.6 s;
# allow 0.65-2.0 s for serves, volleys, and stretched defensive shots.
groups=[]; cur=[]
for e in events:
    if not cur or sec(e[0]-cur[-1][0]) <= 2.0:
        cur.append(e)
    else:
        if len(cur)>=2: groups.append(cur)
        cur=[e]
if len(cur)>=2: groups.append(cur)

for g in groups:
    gaps=[sec(g[i][0]-g[i-1][0]) for i in range(1,len(g))]
    # Split out trains contaminated with dense speech/applause clicks.
    good=sum(.65 <= d <= 2.0 for d in gaps)
    if len(g)>=3 and good >= len(gaps)*0.75:
        print(f"{sec(g[0][0]):8.3f} {sec(g[-1][0]):8.3f} n={len(g):2d} " +
              " gaps="+",".join(f"{d:.2f}" for d in gaps)+
              " peaks="+",".join(str(e[1]) for e in g))

