import csv, statistics

def load(path):
    out=[]
    with open(path,newline="") as f:
        for r in csv.DictReader(f): out.append((int(r['peak']),float(r['rms']),int(r['zcr'])))
    return out
h=load('/workspace/work/hp_bins.csv'); a=load('/workspace/work/full_bins.csv')
events=[]
for i in range(20,len(h)-100):
    p,r,z=h[i]
    if p<400 or p != max(v[0] for v in h[i-10:i+11]) or p/(r+1)<2.4: continue
    if events and i-events[-1] < 35:
        if p>h[events[-1]][0]: events[-1]=i
    else: events.append(i)
print('time,hpeak,hrms,impulse,band,quiet_med,quiet_p30,quiet_frac,zcr')
for i in events:
    q=[a[j][1] for j in range(i-100,i+101) if abs(j-i)>5]
    qs=sorted(q); med=qs[len(q)//2]; p30=qs[len(q)*3//10]
    frac=sum(x<700 for x in q)/len(q)
    print(f'{i*55/11025:.5f},{h[i][0]},{h[i][1]:.1f},{h[i][0]/(h[i][1]+1):.2f},{h[i][1]/(a[i][1]+1):.3f},{med:.1f},{p30:.1f},{frac:.3f},{h[i][2]}')

